    def reset_api_version(self, api_url: str, binary_api_url: str, version: int | str):
        if isinstance(version, int):
            self.base_url = "/".join([api_url, "api", "v" + str(version)])
            self.binary_api_url = "/".join([binary_api_url, "api", "v" + str(version)])
        elif isinstance(version, str):
            self.base_url = "/".join([api_url, "api", version])
            self.binary_api_url = "/".join([binary_api_url, version])
        else:
            raise TypeError(f"Unknown value for api_ver: {version} ({type(version)})")

    @staticmethod
    def getReqId() -> str:
        """
        Генерация уникального ID запроса
        :return: str
        """
        return str(uuid1())

    def allure_attach(
        self,
        response: httpx.Response,
        return_str: bool = False,
        *args,
        **kwargs,
    ) -> Optional[str]:
        """
        Функция для логирования запроса-ответа в Allure отчете

        """
        response.encoding = "UTF-8"

        date_str = str(datetime.now())
        headers_str = "\n".join([f"{k}: {v}" for k, v in response.request.headers.items()])

        text = f"{date_str}\n" f"{response.request.method} {response.request.url}\n" f"{headers_str}\n"

        if response.request.content:
            if isinstance(response.request.content, str):
                text += "\n" f"{unquote(response.request.content)}"

            elif isinstance(response.request.content, (bytes, bytearray)) and len(response.request.content) < 1000:
                try:
                    text += "\n" f"{unquote(response.request.content.decode())}"
                except UnicodeDecodeError:
                    text += "\n" f"Bytes {len(response.request.content)}"

            else:
                text += "\n" f"{type(response.request.content)}"

        text = text.strip()

        headers_str = "\n".join([f"{k}: {v}" for k, v in response.headers.items()])

        text += f"\n\n{response.status_code} {response.reason_phrase}\n" f"IP: {self.forced_ip}\n" f"{headers_str}\n"

        if response.text:
            if isinstance(response.text, str):
                text += "\n" f"{response.text}"
            else:
                text += "\n" f"{response.content.decode()}"

        self.logger.info(text)

        url_path = response.url.path.replace("/", "_")

        allure.attach(
            text,
            name=f"{url_path}.log.txt",
            extension=allure.attachment_type.TEXT,
        )
        if return_str:
            return text

        return None

    async def request(
        self,
        method: Literal["GET", "POST"],
        url: str,
        headers: Optional[dict[str, str]] = None,
        params: Optional[dict] = None,
        json: Optional[dict] = None,
        data: Optional[dict] = None,
        files=None,
        ignore_check: bool = False,
        timeout: tuple[int | float, int | float] | int | float = (5.0, 40.0),
        allow_redirects: bool = True,
    ) -> Union[dict, httpx.Response, str]:
        """
        Прокси-метод для всех запросов
        """
        self.request_counter += 1

        response = ValueError

        MAX_RETRIES = 2

        for i in range(MAX_RETRIES + 1):
            try:
                response = await self.session.request(
                    method=method,
                    url=url,
                    headers=headers,
                    params=params,
                    json=json,
                    data=data,
                    files=files,
                    timeout=timeout,
                    follow_redirects=allow_redirects,
                )
                response.encoding = "UTF-8"

                if not ignore_check:
                    return await self.check_response(response=response)

                else:
                    response_content_type = response.headers.get("Content-Type") or response.headers.get(
                        "content-type",
                        "generic",
                    )
                    self.logger.info(f"response_content_type: {response_content_type}")
                    if response_content_type.startswith("application/json"):
                        return response.json()
                    else:
                        return response.text

            except (httpx.ConnectError, TooManyRedirectsException, OrgstructureException) as error:
                if i < MAX_RETRIES:
                    self.logger.warning(error)
                    with tracer.start_as_current_span("asyncio.sleep"):
                        await asyncio.sleep(i)
                    continue
                else:
                    raise error

            except RequestException as error:
                if i == MAX_RETRIES or "rapi/folders" in url:
                    raise
                with tracer.start_as_current_span("asyncio.sleep"):
                    await asyncio.sleep(i)

                self.logger.error(error)

                if self.session_started and "startSession" not in url and "clientLogin" not in url:
                    await self.login()

                for request_parameter in (params, json, data):
                    if request_parameter is not None and "aimsid" in request_parameter:
                        request_parameter["aimsid"] = self.aimsid

            except (RatelimitException, ValueError, Exception):
                raise

        else:
            response.raise_for_status()
            return response

    @tracer.start_as_current_span("aclient.restart_session")
    async def restart_session(self):
        """
        Метод для рестарта сессии
        """
        result = await self.wim_aim_startSession()
        self.aimsid = result["response"]["data"]["aimsid"]
        self.fetch_url = result["response"]["data"]["fetchBaseURL"]
        self.session_started = True

    @tracer.start_as_current_span("aclient.check_response")
    async def check_response(self, response: httpx.Response) -> Union[dict, httpx.Response]:
        """
        Проверка кода ответа API
        """
        try:
            response_json = response.json()
        except Exception as error:
            self.logger.error(error)
            response_json = {"not_json": True}

        response_status_code = int(
            (response_json.get("status") if isinstance(response_json.get("status"), int) else None)
            or response_json.get("status", {}).get("code")
            or response_json.get("response", {}).get("statusCode")
            or response_json.get("status")
            or response.status_code,
        )

        try:
            response_status_state = str(response_json.get("response", {}).get("data", {}).get("state")) or "NoStateText"
        except Exception as error:
            self.logger.warning(error)
            response_status_state = "NoStateText"

        try:
            if isinstance(response_json.get("results"), dict):
                results_text = ":".join(
                    ["{id}-{error}".format(**x) for x in response_json.get("results", {}).get("failures", [])],
                )
            else:
                results_text = None

            response_status_text = str(
                response_json.get("description")
                or response_json.get("response", {}).get("statusText")
                or (
                    response_json.get("status", {}).get("reason")
                    if isinstance(response_json.get("status"), dict)
                    else None
                )
                or results_text
                or "NoStatusText",
            )
        except Exception as error:
            self.logger.warning(error)
            response_status_text = "NoStatusText"

        span = get_current_span()
        if span.is_recording():
            span.set_attribute("response_status_code", response_status_code)
            span.set_attribute("response_status_text", response_status_text)
            span.set_attribute("response_status_state", response_status_state)

        if response_status_state == "failed":
            raise SendImStateException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=f'state: "{response_status_state}", status_text: {response_status_text}',
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 400 and "statusDetailCode 7" in response_status_text:
            raise RequestException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 502:
            raise BadGatewayException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 423:
            raise WAFRequestBlocked(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 40300 and "/files/" in response.url.path:
            raise RequestException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [20070] and "rapi/group/members/add" in response.url.path:
            raise UserMustJoinByLinkException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 301:
            raise TooManyRedirectsException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 330:
            raise RequestException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [400, 40000]:
            raise BadRequestException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [40008, 40403, 40405, 40401] and "rapi/orgstructure" in response.url.path:
            raise OrgstructureException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [40008, 40403, 40405, 40401] and "rapi/getHistory" in response.url.path:
            raise GetHistoryException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 40401:
            return response

        elif response_status_code in [403, 40003, 40300, 40200]:
            if (
                "auth check failed" in response_status_text or response_status_text == "Invalid token"
            ) and "rapi/message/send" not in response.url.path:
                raise RequestException(
                    env=self.env,
                    path_url=response.url.path,
                    response_status_code=response_status_code,
                    response_status_text=response_status_text,
                    http_request_plain_text=self.allure_attach(response=response, return_str=True),
                )
            elif (
                response_status_code == 40200
                and response_status_text == "Invalid token"
                and "rapi/message/send" in response.url.path
            ):
                raise InvalidAimsidException(
                    env=self.env,
                    path_url=response.url.path,
                    response_status_code=response_status_code,
                    response_status_text=response_status_text,
                    http_request_plain_text=self.allure_attach(response=response, return_str=True),
                )
            else:
                raise AccessDeniedException(
                    env=self.env,
                    path_url=response.url.path,
                    response_status_code=response_status_code,
                    response_status_text=response_status_text,
                    http_request_plain_text=self.allure_attach(response=response, return_str=True),
                )

        elif response_status_code in [404, 40400, 40004]:
            if "rapi/message/send" in response.url.path:
                raise BadTargetException(
                    env=self.env,
                    path_url=response.url.path,
                    response_status_code=response_status_code,
                    response_status_text=response_status_text,
                    http_request_plain_text=self.allure_attach(response=response, return_str=True),
                )
            else:
                raise HttpNotFoundException(
                    env=self.env,
                    path_url=response.url.path,
                    response_status_code=response_status_code,
                    response_status_text=response_status_text,
                    http_request_plain_text=self.allure_attach(response=response, return_str=True),
                )

        elif response_status_code in [429, 430]:
            raise RatelimitException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in (460, 462, 40000):
            raise MissingParameterException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 40010:
            raise TaskCreationErrorException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 40011:
            raise PollCreationErrorException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 40013:
            raise MessageIsTooBigException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 40021:
            raise ScheduledTimeIsTooFarInFutureException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 40022:
            raise ScheduledMessagesLimitReachedException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code == 40500:
            raise RatelimitException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [40607, 603]:
            if not response_json.get("not_json", False):
                return response_json
            else:
                return response

        elif 400 <= response_status_code < 500 or 40000 <= response_status_code < 50000:
            raise RequestException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif 200 <= response_status_code < 400 or 20000 <= response_status_code < 40000:
            if not response_json.get("not_json", False):
                return response_json
            else:
                return response

        else:
            raise ServerException(
                env=self.env,
                path_url=response.url.path,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

    async def get(self, path: str, allow_redirects: bool = True, **kwargs) -> Union[dict, str]:
        """
        Оболочка для GET запросов к api ICQ/Myteam
        :param path: path для запроса
        :param allow_redirects: Разрешить следования редиректам
        :param kwargs:
        :return: результат выполнения запроса (код и тело ответа)
        """
        return await self.request(
            method="GET",
            url="/".join([self.base_url, path]),
            params=kwargs,
            allow_redirects=allow_redirects,
        )

    async def post(
        self,
        path: str,
        params: Optional[dict] = None,
        json: Optional[dict] = None,
        data: Optional[dict] = None,
        files=None,
        allow_redirects: bool = True,
    ) -> Union[dict, str]:
        """
        Оболочка для POST запросов к api ICQ/Myteam
        :return: результат выполнения запроса (код и тело ответа)
        """
        return await self.request(
            method="POST",
            url="/".join([self.base_url, path]),
            params=params,
            json=json,
            data=data,
            files=files,
            allow_redirects=allow_redirects,
        )

    async def wim_aim_startSession(self) -> dict:
        """
        Метод используется для создания пользовательской сессии,
        в рамках которой в дальнейшем выполняются запросы,
        требующие идентификатор сессии - aimsid.
        Также метод возвращает fetchBaseURL,
        используемый клиентом в дальнейшем для получения событий от сервера.
        Кроме того, метод позволяет подписаться на события,
        доставляемые при помощи push-уведомлений,
        и получить информацию о пользователе, выполнившем вход в приложение.

        Параметры сессии в дальнейшем могут быть изменены
        при помощи метода /wim/aim/setSessionParam

        Для завершения начатой сессии следует использовать
        метод /wim/aim/endSession
        :return: тело ответа сервера
        """
        return await self.post(
            "wim/aim/startSession",
            data={
                "a": self.token,
                "k": self.devId,
                "ts": int(time.time()),
                "sessionTimeout": 7200,
                "view": "online",
                "mobile": False,
                "events": ",".join(
                    [
                        "myInfo",
                        "presence",
                        "buddylist",
                        "typing",
                        "hiddenChat",
                        "hist",
                        "mchat",
                        "sentIM",
                        "imState",
                        "dataIM",
                        "offlineIM",
                        "userAddedToBuddyList",
                        "service",
                        "lifestream",
                        "apps",
                        "permitDeny",
                        "diff",
                        "webrtcMsg",
                    ],
                ),
                "includePresenceFields": ",".join(
                    [
                        "aimId",
                        "iconId",
                        "bigIconId",
                        "largeIconId",
                        "displayId",
                        "friendly",
                        "offlineMsg",
                        "state",
                        "statusMsg",
                        "userType",
                        "phoneNumber",
                        "cellNumber",
                        "smsNumber",
                        "workNumber",
                        "otherNumber",
                        "capabilities",
                        "ssl",
                        "abPhoneNumber",
                        "moodIcon",
                        "lastName",
                        "abPhones",
                        "abContactName",
                        "lastseen",
                        "mute",
                        "counterEnabled",
                        "livechat",
                        "official",
                        "public",
                        "autoAddition",
                        "readonly",
                        "nick",
                        "bot",
                    ],
                ),
                "assertCaps": ",".join(self.assert_caps),
                "interestCaps": ",".join(
                    [
                        "8eec67ce70d041009409a7c1602a5c84",
                        "094613504c7f11d18222444553540000," "094613514c7f11d18222444553540000",
                        "094613503c7f11d18222444553540000",
                    ],
                ),
                "language": self.language,
                "clientName": self.client_name,
                "clientVersion": self.client_version,
                "buildNumber": self.client_build_number,
                "deviceId": self.device_id,
            },
        )

    async def wim_aim_setSessionParam(self, **kwargs) -> dict:
        r"""
        Изменить параметры пользовательской сессии
        Метод используется для изменения параметров сессии, установленных при вызове метода /wim/aim/startSession
        :param r: Уникальный идентификатор запроса. Используется для поиска запросов в логах сервера и предотвращения
        повторного исполнения неидемпотентных запросов, перепосылаемых клиентом при отсутствии ответа
        :param aimsid: Идентификатор пользовательской сессии, полученный в результате выполнения
        запроса /wim/aim/startSession
        :param k: Ключ приложения. Выдаётся администраторами ICQ индивидуально для каждой версии клиентского приложени
        param sessionTimeout: Время жизни сессии в секундах \n
        param pollTimeout: Таймаут в секундах для long-polling-запроса /bos/fetchEvents (используется для
        формирования fetchBaseURL) \n
        param includePresenceFields: Множество имён полей, которые клиент желает получать в событиях типа presence
        в методе /bos/fetchEvents \n
        param language: Локаль пользователя в формате xx-YY, где xx - язык в формате ISO 639-1, а YY - код страны
        в формате ISO 3166-1 alpha-2 \n
        param iPhonePushVersion: Apple Push Notification. Версия формата Push-уведомлений \n
        param iPhoneDevToken: Apple Push Notification. Токен устройства в кодировке Base16 \n
        param iPhoneVoipDevToken: Apple Push Notification. VOIP-токен устройства в кодировке Base16 \n
        param iPhoneBundleId: Apple Push Notification. Идентификатор приложения \n
        param iPhoneSound: Apple Push Notification. Значение параметра "sound", отправляемого в Push-уведомлениях \n
        param iPhoneRingSound: Apple Push Notification. Значение параметра "sound", отправляемого
        в VOIP-push-уведомлениях \n
        param iPhoneLocKey: Apple Push Notification. Значение параметра "loc-key", отправляемого в Push-уведомлениях \n
        param iPhoneActionKey: Apple Push Notification. Значение параметра "action-loc-key", отправляемого
        в Push-уведомлениях \n
        param iPhoneLocArgs: Apple Push Notification. Аргументы, требуемые для локализации Push-уведомления
            srcName - Имя отправителя
            srcId - ID отправителя
            destName - Имя получателя
            timestamp - Время отправки сообщения
            message - Текст сообщения \n
        param iPhoneBadge: Apple Push Notification. Отправлять "badge" в Push-уведомлениях \n
        param idfa: The Identifier for Advertisers - уникальный номер устройства от компании Apple \n
        :return: тело ответа сервера
        """
        return await self.post(
            "wim/aim/setSessionParam",
            data={
                "r": self.getReqId(),
                "aimsid": self.aimsid,
                "k": self.devId,
                **kwargs,
            },
        )

    async def wim_aim_endSession(self) -> dict:
        """
        Метод используется для завершения сессии,
        начатой посредством вызова метода /wim/aim/startSession
        :return: тело ответа сервера
        """
        return await self.post(
            "wim/aim/endSession",
            data={"r": self.getReqId(), "aimsid": self.aimsid},
        )

    async def wim_auth_clientLogin(self, pwd: str, tokenType: str = "longterm") -> dict:
        """
        Устаревшая авторизация
        :return: тело ответа сервера
        """
        return await self.post(
            "wim/auth/clientLogin",
            params={
                "s": self.uin,
                "k": self.devId,
                "pwd": pwd,
                "devId": self.devId,
                "tokenType": tokenType,
            },
        )

    async def wim_auth_clientLoginFirst(self, tokenType: str = "otp_via_email") -> dict:
        """
        Устаревшая авторизация
        :return: тело ответа сервера
        """
        return await self.post(
            "wim/auth/clientLogin",
            params={
                "s": self.uin,
                "pwd": 1,
                "devId": self.devId,
                "tokenType": tokenType,
            },
            json={"pwd": 1},
        )

