    async def get_otp_token_from_mail(self, password: str, imap_url: str, invoke_token: bool = False):
        if not invoke_token:
            await self.wim_auth_clientLoginFirst()

        result = await self.request(
            method="GET",
            url="https://im-qa-helper.mail.msk/api/v1/night/otp",
            params={
                "uin": self.uin,
                "email": self.uin,
                "password": password,
                "backend_url": self.api_url_without_version,
                "imap_url": imap_url,
                "invoke_token": invoke_token,
            },
            headers={"X-Token": "X-Tests"},
            ignore_check=True,
        )

        return result["otp_token"]

    async def get_otp_token_from_mail_local(self, password: str, imap_url: str, invoke_token: bool = False):
        ssl_context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
        ssl_context.check_hostname = False
        ssl_context.verify_mode = ssl.CERT_NONE

        imap_client = aioimaplib.IMAP4_SSL(imap_url, ssl_context=ssl_context)
        await imap_client.wait_hello_from_server()

        await imap_client.login(self.uin, password)

        await imap_client.select("INBOX")
        data = await imap_client.search(None, "ALL")

        message_nums = data.lines[0].decode().split()

        if message_nums:
            for num in message_nums:
                await imap_client.store(num, "+FLAGS", "\\Deleted")

            await imap_client.expunge()

        if invoke_token:
            await self.wim_auth_clientLoginFirst()
            with tracer.start_as_current_span("asyncio.sleep"):
                await asyncio.sleep(5)

        otp_token = None

        for i in range(5):
            data = await imap_client.uid("fetch", "1:*", "RFC822")

            for msg in data.lines[::-1]:
                if isinstance(msg, bytearray):
                    mail_line = msg.decode().splitlines()
                    self.logger.info(f"otp_token - {otp_token}")
                    otp_token = mail_line[-2]
                if otp_token is not None:
                    break

            if otp_token is not None:
                break
            with tracer.start_as_current_span("asyncio.sleep"):
                await asyncio.sleep(i)

        assert otp_token, "OTP Token not found in incoming messages"

        return otp_token

    async def get_otp_token_from_chat(self):
        await self.wim_auth_clientLoginFirst()

        with tracer.start_as_current_span("asyncio.sleep"):
            await asyncio.sleep(3)

        response = await self.session.post(
            "https://im-qa-helper.mail.msk/api/v1/night/dev/otp",
            params={"uin": self.uin},
        )
        response.encoding = "utf-8"
        response = response.json()

        return response["token"]

    async def get_otp_token_from_chat_local(self):
        async def get_events():
            return (
                await self.session.get(
                    url="https://api.internal.myteam.mail.ru/bot/v1/events/get",
                    params={
                        "token": "001.2731743155.3227401719:1000001264",
                        "lastEventId": 0,
                        "pollTime": 30,
                    },
                )
            ).json()

        event_coro = get_events()

        await self.wim_auth_clientLoginFirst()

        event_response = await event_coro

        with tracer.start_as_current_span("asyncio.sleep"):
            await asyncio.sleep(2)

        for event in reversed(event_response["events"]):
            return event["payload"]["text"].splitlines()[1]

        else:
            raise ValueError("No OTP token found in events")
